// Synthetic-data tests for archive bootstrap, database writes and /archive/status.
// Everything here is invented: fake ids, fake names, generated bytes for "videos".
// Run with:  npm test

import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import zlib from 'node:zlib';

// The downloader reads these at import time, so set them first.
const SCRATCH = await fs.mkdtemp(path.join(os.tmpdir(), 'ttpull-test-'));
process.env.STATE_DIR = path.join(SCRATCH, 'state');
process.env.ARCHIVE_DIR = path.join(SCRATCH, 'unused');

const db = await import('../archive-db.js');

const FAKE = {
  ids: ['9000000000000000001', '9000000000000000002', '9000000000000000003'],
  author: 'fake_author_one',
  nickname: 'Fake Nickname One',
  caption: 'fake caption text',
};

// ── helpers ──────────────────────────────────────────────────────────────────

const newArchive = async name => {
  const dir = path.join(SCRATCH, name);
  await fs.mkdir(dir, { recursive: true });
  return dir;
};
const appdata = dir => path.join(dir, 'data', '.appdata');
const FILE_VARS = {
  'db_videos.js': 'dbv_base64',
  'db_authors.js': 'dba_base64',
  'db_texts.js': 'dbvd_base64',
  'db_likes.js': 'db_base64',
  'db_bookmarked.js': 'dbb_base64',
};

// Independent reader, written separately from archive-db.js on purpose.
async function readFileDb(dir, file) {
  const raw = await fs.readFile(path.join(appdata(dir), file), 'utf8');
  const m = raw.match(/^window\.([a-z_0-9]+)="([A-Za-z0-9+/=]+)";$/);
  assert.ok(m, `${file}: wrapper format`);
  assert.equal(m[1], FILE_VARS[file], `${file}: variable name`);
  return JSON.parse(zlib.gunzipSync(Buffer.from(m[2], 'base64')).toString('utf8'));
}

const walk = async dir => {
  const out = [];
  for (const e of await fs.readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) out.push(full + '/', ...(await walk(full)));
    else out.push(full);
  }
  return out;
};
const rel = (dir, list) => list.map(p => path.relative(dir, p)).sort();

// Fail the test if anything sensitive-looking ever reaches a log line.
const leaks = lines => lines.filter(l =>
  FAKE.ids.some(id => l.includes(id)) || l.includes(FAKE.author) || l.includes(FAKE.nickname) || l.includes(FAKE.caption));

const withMode = async (m, fn) => {
  const before = process.env.DB_UPDATE;
  process.env.DB_UPDATE = m;
  try { return await fn(); } finally { if (before === undefined) delete process.env.DB_UPDATE; else process.env.DB_UPDATE = before; }
};

const sampleVideos = () => FAKE.ids.slice(0, 2).map((id, i) => ({
  id, desc: FAKE.caption, authorId: 'fake_author_id_1', authorName: FAKE.author, nickname: FAKE.nickname,
  createTime: 1700000000 + i, itemMute: false, diggCount: 3, playCount: 7, size: 1234,
  followerCount: 10, heartCount: 20, videoCount: 5,
}));

// ── bootstrap ────────────────────────────────────────────────────────────────

test('bootstrap creates exactly the expected layout in an empty folder', async () => {
  const dir = await newArchive('empty-write');
  const logs = [];
  const r = await withMode('write', () => db.bootstrapArchive(dir, l => logs.push(l)));

  assert.deepEqual(r.created.sort(), Object.keys(FILE_VARS).sort());
  assert.deepEqual(rel(dir, await walk(dir)), [
    'data/',
    'data/.appdata/',
    'data/.appdata/db_authors.js',
    'data/.appdata/db_bookmarked.js',
    'data/.appdata/db_likes.js',
    'data/.appdata/db_texts.js',
    'data/.appdata/db_videos.js',
    'data/Favorites/',
    'data/Favorites/covers/',
    'data/Favorites/videos/',
    'data/Likes/',
    'data/Likes/covers/',
    'data/Likes/videos/',
  ].map(p => p.replace(/\/$/, '')).sort().map(p => p));
  assert.equal(leaks(logs).length, 0);
});

test('bootstrap does not create viewer files', async () => {
  const dir = await newArchive('no-viewer');
  await withMode('write', () => db.bootstrapArchive(dir, () => {}));
  const all = rel(dir, await walk(dir)).join('\n');
  assert.ok(!/Archive\.html|app\.js/.test(all));
});

test('empty database files have the expected shapes', async () => {
  const dir = await newArchive('shapes');
  await withMode('write', () => db.bootstrapArchive(dir, () => {}));

  assert.deepEqual(await readFileDb(dir, 'db_videos.js'), {});
  assert.deepEqual(await readFileDb(dir, 'db_authors.js'), {});
  assert.deepEqual(await readFileDb(dir, 'db_texts.js'), {});

  const likes = await readFileDb(dir, 'db_likes.js');
  assert.deepEqual(Object.keys(likes).sort(), ['likes', 'schemaVersion', 'user']);
  assert.equal(likes.schemaVersion, 7);
  assert.deepEqual(Object.keys(likes.user).sort(), ['id', 'nickname', 'uid', 'uniqueId']);
  assert.deepEqual(Object.keys(likes.likes).sort(), ['downloaded', 'lastRun', 'numDisappeared', 'officialList', 'total']);
  assert.deepEqual(likes.likes.officialList, []);
  assert.deepEqual(likes.likes.downloaded, []);

  const marks = await readFileDb(dir, 'db_bookmarked.js');
  assert.deepEqual(Object.keys(marks).sort(), ['downloaded', 'lastRun', 'numDisappeared', 'officialList', 'total']);
  assert.deepEqual(marks.lastRun, { start: 0, finish: 0 });
});

test('bootstrap is idempotent and leaves existing files untouched', async () => {
  const dir = await newArchive('idempotent');
  await withMode('write', () => db.bootstrapArchive(dir, () => {}));
  const snapshot = async () => Object.fromEntries(await Promise.all(
    Object.keys(FILE_VARS).map(async f => [f, [(await fs.readFile(path.join(appdata(dir), f))).toString('base64'), (await fs.stat(path.join(appdata(dir), f))).mtimeMs]])));
  const before = await snapshot();
  await new Promise(r => setTimeout(r, 15));
  const again = await withMode('write', () => db.bootstrapArchive(dir, () => {}));
  assert.deepEqual(again.created, []);
  assert.deepEqual(await snapshot(), before);
  assert.deepEqual((await fs.readdir(appdata(dir))).sort(), Object.keys(FILE_VARS).sort(), 'no leftover temp files');
});

test('bootstrap never touches a partial archive', async () => {
  const dir = await newArchive('partial');
  await fs.mkdir(appdata(dir), { recursive: true });
  const sentinel = 'window.dbv_base64="SENTINEL-NOT-REAL";';
  await fs.writeFile(path.join(appdata(dir), 'db_videos.js'), sentinel);
  const logs = [];
  const r = await withMode('write', () => db.bootstrapArchive(dir, l => logs.push(l)));
  assert.deepEqual(r.created, []);
  assert.equal(await fs.readFile(path.join(appdata(dir), 'db_videos.js'), 'utf8'), sentinel);
  assert.deepEqual(await fs.readdir(appdata(dir)), ['db_videos.js']);
});

test('exclusive create never replaces an existing file', async () => {
  const dir = await newArchive('exclusive');
  const file = path.join(dir, 'existing.js');
  await fs.writeFile(file, 'ORIGINAL');
  assert.equal(await db.createExclusive(file, 'REPLACEMENT'), false);
  assert.equal(await fs.readFile(file, 'utf8'), 'ORIGINAL');
  assert.equal(await db.createExclusive(path.join(dir, 'new.js'), 'NEW'), true);
  assert.deepEqual((await fs.readdir(dir)).sort(), ['existing.js', 'new.js'], 'no temp files left');
});

test('dry and off modes create nothing', async () => {
  for (const m of ['dry', 'off']) {
    const dir = await newArchive(`mode-${m}`);
    const r = await withMode(m, () => db.bootstrapArchive(dir, () => {}));
    assert.deepEqual(r.created, []);
    assert.deepEqual(await fs.readdir(dir), []);
  }
});

// ── status ───────────────────────────────────────────────────────────────────

test('archive status: not initialised, then empty, then counted', async () => {
  const dir = await newArchive('status');
  assert.deepEqual(await db.archiveStatus(dir), {
    initialized: false, likes: { downloaded: 0, official: 0 }, bookmarks: { downloaded: 0, official: 0 }, lastWrite: null,
  });

  await withMode('write', () => db.bootstrapArchive(dir, () => {}));
  const empty = await db.archiveStatus(dir);
  assert.equal(empty.initialized, true);
  assert.deepEqual(empty.likes, { downloaded: 0, official: 0 });
  assert.deepEqual(empty.bookmarks, { downloaded: 0, official: 0 });
  assert.match(empty.lastWrite, /^\d{4}-\d\d-\d\dT[\d:.]+Z$/);

  const logs = [];
  await withMode('write', () => db.registerVideos(dir, 'likes', sampleVideos(), l => logs.push(l)));
  await withMode('write', () => db.registerVideos(dir, 'bookmarked', sampleVideos().slice(0, 1), l => logs.push(l)));
  const filled = await db.archiveStatus(dir);
  assert.deepEqual(filled.likes, { downloaded: 2, official: 2 });
  assert.deepEqual(filled.bookmarks, { downloaded: 1, official: 1 });
  assert.deepEqual(Object.keys(filled).sort(), ['bookmarks', 'initialized', 'lastWrite', 'likes']);
  assert.equal(JSON.stringify(filled).includes(FAKE.ids[0]), false, 'status must not contain ids');
  assert.equal(leaks(logs).length, 0, 'database code must not log ids, names or captions');
});

// ── database writes without any viewer files ─────────────────────────────────

test('registering videos works on a bootstrapped archive and backs up what it changes', async () => {
  const dir = await newArchive('register');
  const logs = [];
  const log = l => logs.push(l);
  await withMode('write', () => db.bootstrapArchive(dir, log));
  const r = await withMode('write', () => db.registerVideos(dir, 'likes', sampleVideos(), log));
  assert.equal(r.added, 2);

  const videos = await readFileDb(dir, 'db_videos.js');
  assert.deepEqual(Object.keys(videos).sort(), FAKE.ids.slice(0, 2).sort());
  assert.deepEqual(Object.keys(videos[FAKE.ids[0]]).sort(), ['authorId', 'createTime', 'diggCount', 'itemMute', 'playCount', 'size']);
  const authors = await readFileDb(dir, 'db_authors.js');
  assert.deepEqual(authors.fake_author_id_1.uniqueIds, [FAKE.author]);
  assert.deepEqual(Object.keys(authors.fake_author_id_1).sort(), ['followerCount', 'heartCount', 'nicknames', 'uniqueIds', 'videoCount']);
  assert.equal((await readFileDb(dir, 'db_texts.js'))[FAKE.ids[0]], FAKE.caption);
  const likes = (await readFileDb(dir, 'db_likes.js')).likes;
  assert.deepEqual(likes.officialList, FAKE.ids.slice(0, 2));
  assert.deepEqual(likes.downloaded, FAKE.ids.slice(0, 2));

  const backups = (await fs.readdir(path.join(appdata(dir), 'backups'))).filter(n => n.startsWith('ttpull-'));
  assert.equal(backups.length, 1, 'one backup folder');
  const saved = (await fs.readdir(path.join(appdata(dir), 'backups', backups[0]))).sort();
  assert.deepEqual(saved, ['db_authors.js', 'db_likes.js', 'db_texts.js', 'db_videos.js']);

  // a second registration of the same videos changes nothing and makes no backup
  const again = await withMode('write', () => db.registerVideos(dir, 'likes', sampleVideos(), log));
  assert.equal(again.added, 0);
  assert.equal((await fs.readdir(path.join(appdata(dir), 'backups'))).length, 1);
  assert.equal(leaks(logs).length, 0);
});

test('registering on an empty folder creates the archive first (write mode)', async () => {
  const dir = await newArchive('register-from-nothing');
  await withMode('write', () => db.registerVideos(dir, 'bookmarked', sampleVideos(), () => {}));
  assert.equal((await db.archiveStatus(dir)).initialized, true);
  assert.deepEqual((await readFileDb(dir, 'db_bookmarked.js')).downloaded, FAKE.ids.slice(0, 2));
});

test('dry mode on an empty folder writes nothing', async () => {
  const dir = await newArchive('register-dry');
  await withMode('dry', () => db.registerVideos(dir, 'likes', sampleVideos(), () => {}));
  assert.deepEqual(await fs.readdir(dir), []);
});

test('official list refresh and last-run stamp work without viewer files', async () => {
  const dir = await newArchive('refresh');
  await withMode('write', () => db.registerVideos(dir, 'likes', sampleVideos(), () => {}));
  const r = await withMode('write', () => db.refreshOfficialList(dir, 'likes', [FAKE.ids[2], FAKE.ids[0]], () => {}));
  assert.equal(r.applied, true);
  const likes = (await readFileDb(dir, 'db_likes.js')).likes;
  assert.deepEqual(likes.officialList, [FAKE.ids[2], FAKE.ids[0]]);
  assert.equal(likes.numDisappeared, 1);
  assert.equal(await withMode('write', () => db.touchLastRun(dir, 'likes')), true);
  assert.ok((await readFileDb(dir, 'db_likes.js')).likes.lastRun.finish > 0);
});

// ── end to end: downloader on a bootstrapped archive, served by a local fake ─────────

test('downloader fills a bootstrapped archive from a local fake server', async () => {
  const dir = await newArchive('e2e');
  process.env.ARCHIVE_DIR = dir; // read when the downloader module loads
  const mp4 = n => { const b = Buffer.alloc(24 * 1024 + n, n); b.write('ftypisom', 4); return b; };
  const server = http.createServer((req, res) => {
    if (req.url.endsWith('.mp4')) res.end(mp4(req.url.length));
    else res.end(Buffer.from('generated-cover-bytes'));
  }).listen(0);
  await new Promise(r => server.once('listening', r));
  const base = `http://127.0.0.1:${server.address().port}`;

  const quiet = { log: console.log, error: console.error };
  console.log = console.error = () => {};
  try {
    await withMode('write', async () => {
      const { downloadVideos } = await import('../downloader.js');
      const mk = (id, i) => ({ ...sampleVideos()[0], id, videoUrl: `${base}/v/${i}.mp4`, coverUrl: `${base}/c/${i}.jpg` });
      await downloadVideos({ cookies: [], ctx: {} }, {
        likes: [mk(FAKE.ids[0], 1), mk(FAKE.ids[1], 2)],
        bookmarks: [mk(FAKE.ids[2], 3)],
      });
    });
  } finally {
    console.log = quiet.log; console.error = quiet.error;
    server.close();
  }

  for (const id of FAKE.ids.slice(0, 2)) {
    assert.ok((await fs.stat(path.join(dir, 'data/Likes/videos', `${id}.mp4`))).size > 10 * 1024);
    await fs.access(path.join(dir, 'data/Likes/covers', `${id}.jpg`));
  }
  assert.ok((await fs.stat(path.join(dir, 'data/Favorites/videos', `${FAKE.ids[2]}.mp4`))).size > 10 * 1024);
  const st = await db.archiveStatus(dir);
  assert.deepEqual(st.likes, { downloaded: 2, official: 2 });
  assert.deepEqual(st.bookmarks, { downloaded: 1, official: 1 });
  assert.ok(!(await fs.readdir(path.join(dir, 'data/Likes/videos'))).some(f => f.endsWith('.part')), 'no partial files left');
});

test('cleanup', async () => { await fs.rm(SCRATCH, { recursive: true, force: true }); });
